  const args = parseArgumentsOrExit(argv, programName);
  if (!args) {
    return;
  }

  const items = args.a.split(',');
  console.log(unitLen(items, args.b));
  console.log(cardinalize(args.b, items.length));
  console.log(unitLen(items.slice(0, 3), args.b));
  console.log(cardinalize(args.b, 1));
  console.log(unitLen(items.slice(0, 1), args.b));
}

