]);

const O_ES_WORDS = new Set([
  'buffalo',
  'cargo',
  'echo',
  'embargo',
  'hero',
  'mosquito',
  'potato',
  'tomato',
  'torpedo',
  'veto',
]);

const CONSONANT_Y_PATTERN = /[^aeiou]y$/;

function pluralizeLowerCase(word) {
  if (word === '') {
    return '';
  }

  if (IRREGULAR_PLURALS.has(word)) {
    return IRREGULAR_PLURALS.get(word);
  }

  if (VES_WORDS.has(word)) {
    if (word.endsWith('fe')) {
      return `${word.slice(0, -2)}ves`;
    }

    return `${word.slice(0, -1)}ves`;
  }

  if (O_ES_WORDS.has(word)) {
    return `${word}es`;
  }

  if (CONSONANT_Y_PATTERN.test(word)) {
    return `${word.slice(0, -1)}ies`;
  }

  if (word.endsWith('ch') || word.endsWith('sh') || word.endsWith('s')) {
    return `${word}es`;
  }

  return `${word}s`;
}

export function pluralize(word) {
  const source = `${word}`;
  const lowerCasePlural = pluralizeLowerCase(source.toLowerCase());
  return applySourceCase(source, lowerCasePlural);
}

export function cardinalize(word, count) {
  const source = `${word}`;
  return count === 1 ? source : pluralize(source);
}

import { cardinalize } from './cardinalize.mjs';

export function countItems(value) {
  if (value == null) {
    return 0;
  }

  if (typeof value.length === 'number') {
    return value.length;
  }

  if (typeof value.size === 'number') {
    return value.size;
  }

  let count = 0;
  for (const _item of value) {
    count += 1;
  }
  return count;
}

export function unitLen(value, unitName) {
  const count = countItems(value);
  if (count === 0) {
    return `No ${cardinalize(unitName, 0)}`;
  }

  return `${count} ${cardinalize(unitName, count)}`;
}

