 34	export function parseArguments(argv) {
 35	  const values = {
 36	    a: undefined,
 37	    b: undefined,
 38	  };
 39	  const extras = [];
 40	  let afterDoubleDash = false;
 41	
 42	  for (let index = 0; index < argv.length; index += 1) {
 43	    const token = argv[index];
 44	
 45	    if (afterDoubleDash) {
 46	      extras.push(token);
 47	      continue;
 48	    }
 49	
 50	    if (token === '--') {
 51	      afterDoubleDash = true;
 52	      continue;
 53	    }
 54	
 55	    if (token === '-h' || token === '--help') {
 56	      return { help: true };
 57	    }
 58	
 59	    if (token === '--a' || token === '--b') {
 60	      const key = token.slice(2);
 61	      const value = argv[index + 1];
 62	      if (isOptionLikeToken(value)) {
 63	        throw new ArgumentParserError(needsValueError(token));
 64	      }
 65	
 66	      values[key] = value;
 67	      index += 1;
 68	      continue;
 69	    }
 70	
 71	    if (token.startsWith('--a=')) {
 72	      values.a = token.slice(4);
 73	      continue;
 74	    }
 75	
 76	    if (token.startsWith('--b=')) {
 77	      values.b = token.slice(4);
 78	      continue;
 79	    }
 80	
 81	    extras.push(token);
 82	  }
 83	
 84	  const missing = [];
 85	  if (values.a === undefined) {
 86	    missing.push('--a');
 87	  }
 88	  if (values.b === undefined) {
 89	    missing.push('--b');
 90	  }
 91	
 92	  if (missing.length > 0) {
 93	    throw new ArgumentParserError(`the following arguments are required: ${missing.join(', ')}`);
 94	  }
 95	
 96	  if (extras.length > 0) {
 97	    throw new ArgumentParserError(`unrecognized arguments: ${extras.join(' ')}`);
 98	  }
 99	
100	  return values;
